package david.manager;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Explicitly started, token-protected, read-only remote and MCP servers. */
public final class LocalService {
 private final File defaultRoot;private final Map<String,Server>running=new HashMap<>();private final ExecutorService clients=Executors.newFixedThreadPool(3);
 LocalService(File root){defaultRoot=root;}
 synchronized JSONObject action(JSONObject a)throws Exception{String kind=a.optString("kind","remote"),op=a.optString("op","status");if(op.equals("stop")){Server s=running.remove(kind);if(s!=null)s.close();}if(op.equals("start")&&!running.containsKey(kind)){File folder=new File(a.optString("path",defaultRoot.getPath())).getCanonicalFile();if(!folder.isDirectory()||!folder.canRead())throw new IOException("Choose a readable folder");Server s=new Server(kind,folder);running.put(kind,s);s.start();}JSONArray list=new JSONArray();for(Server s:running.values())list.put(s.info());return new JSONObject().put("servers",list);}
 synchronized void stop(){for(Server s:running.values())s.close();running.clear();clients.shutdownNow();}
 class Server {
  final String kind,token;final File root;final ServerSocket socket;volatile boolean active=true;
  Server(String k,File f)throws Exception{kind=k;root=f;byte[] bytes=new byte[18];new SecureRandom().nextBytes(bytes);StringBuilder sb=new StringBuilder();for(byte b:bytes)sb.append(String.format("%02x",b&255));token=sb.toString();socket=new ServerSocket();socket.setReuseAddress(true);socket.bind(new InetSocketAddress(kind.equals("mcp")?"127.0.0.1":"0.0.0.0",kind.equals("mcp")?8766:8765));}
  JSONObject info()throws Exception{JSONArray urls=new JSONArray();if(kind.equals("mcp"))urls.put("http://127.0.0.1:8766/mcp");else{Enumeration<NetworkInterface>nis=NetworkInterface.getNetworkInterfaces();while(nis.hasMoreElements()){NetworkInterface ni=nis.nextElement();Enumeration<InetAddress>as=ni.getInetAddresses();while(as.hasMoreElements()){InetAddress ip=as.nextElement();if(ip instanceof Inet4Address&&!ip.isLoopbackAddress())urls.put("http://"+ip.getHostAddress()+":8765/?token="+token);}}}return new JSONObject().put("kind",kind).put("root",root.getPath()).put("token",token).put("urls",urls);}
  void start(){Thread t=new Thread(()->{while(active)try{Socket s=socket.accept();clients.submit(()->serve(s));}catch(IOException e){break;}},"CyberHub-"+kind);t.setDaemon(true);t.start();}
  void close(){active=false;try{socket.close();}catch(IOException ignored){}}
  void serve(Socket s){try(Socket client=s){client.setSoTimeout(8000);InputStream in=client.getInputStream();ByteArrayOutputStream hb=new ByteArrayOutputStream();int b,last=0;while((b=in.read())!=-1){hb.write(b);last=(last<<8)|b;if(last==0x0d0a0d0a)break;if(hb.size()>16384)throw new IOException("Headers too large");}String[] lines=hb.toString("UTF-8").split("\r\n");if(lines.length==0)return;String[] req=lines[0].split(" ");if(req.length<2)return;Map<String,String>headers=new HashMap<>();for(int j=1;j<lines.length;j++){int p=lines[j].indexOf(':');if(p>0)headers.put(lines[j].substring(0,p).toLowerCase(Locale.ROOT),lines[j].substring(p+1).trim());}URI uri=URI.create(req[1]);Map<String,String>q=query(uri.getRawQuery());String auth=headers.getOrDefault("authorization","");boolean authorized=auth.equals("Bearer "+token)||(!kind.equals("mcp")&&token.equals(q.get("token")));if(!authorized){reply(client,401,"text/plain","Token required".getBytes(StandardCharsets.UTF_8));return;}
    if(kind.equals("mcp")){if(!req[0].equals("POST")||!uri.getPath().equals("/mcp")){reply(client,405,"text/plain",new byte[0]);return;}int length=Integer.parseInt(headers.getOrDefault("content-length","0"));if(length<0||length>1048576)throw new IOException("Invalid body length");byte[] body=new byte[length];int off=0;while(off<length){int n=in.read(body,off,length-off);if(n<0)throw new EOFException();off+=n;}JSONObject request=new JSONObject(new String(body,StandardCharsets.UTF_8));if(!request.has("id")){reply(client,202,"application/json",new byte[0]);return;}JSONObject response=rpc(request);reply(client,200,"application/json",response.toString().getBytes(StandardCharsets.UTF_8));return;}
    if(!req[0].equals("GET")){reply(client,405,"text/plain",new byte[0]);return;}String rel=q.getOrDefault("path","");File f=rel.isEmpty()?root:FileOps.contained(root,rel);if(f.isFile()){if(f.length()>FileOps.MAX_EXTRACT)throw new IOException("File too large");OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Disposition: attachment\r\nX-Content-Type-Options: nosniff\r\nContent-Length: "+f.length()+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));try(InputStream input=new FileInputStream(f)){FileOps.copy(input,out,FileOps.MAX_EXTRACT);}return;}
    File[]fs=f.listFiles();if(fs==null)throw new IOException("Folder unavailable");Arrays.sort(fs,Comparator.comparing(File::getName));StringBuilder html=new StringBuilder("<!doctype html><meta name=viewport content='width=device-width'><title>DB Manager</title><style>body{background:#303030;color:#ddd;font:16px system-ui;padding:24px}a{color:#70bfff}li{padding:12px}</style><h1>DB Manager</h1><p>Read-only shared folder</p><ul>");if(!rel.isEmpty())html.append("<li><a href='?token=").append(token).append("'>Home</a></li>");for(File c:fs){if(FilesSupport.symlink(c))continue;String path=root.toPath().relativize(c.toPath()).toString();html.append("<li><a href='?token=").append(token).append("&amp;path=").append(URLEncoder.encode(path,"UTF-8")).append("'>").append(escape(c.getName())).append(c.isDirectory()?"/":"").append("</a></li>");}html.append("</ul>");reply(client,200,"text/html; charset=utf-8",html.toString().getBytes(StandardCharsets.UTF_8));
   }catch(Exception ignored){/* Client disconnect, invalid request, or inaccessible path. */}}
  JSONObject rpc(JSONObject q)throws Exception{JSONObject response=new JSONObject().put("jsonrpc","2.0").put("id",q.get("id"));try{String method=q.getString("method");Object result;
   switch(method){case "initialize":result=new JSONObject().put("protocolVersion","2025-03-26").put("capabilities",new JSONObject().put("tools",new JSONObject())).put("serverInfo",new JSONObject().put("name","DB Manager").put("version","0.1.0"));break;
   case "ping":result=new JSONObject();break;
   case "tools/list":{JSONArray tools=new JSONArray();for(String name:new String[]{"list_files","read_text"})tools.put(new JSONObject().put("name",name).put("description",name.equals("list_files")?"List files within the shared folder":"Read a UTF-8 file within the shared folder (1 MB max)").put("inputSchema",new JSONObject().put("type","object").put("properties",new JSONObject().put("path",new JSONObject().put("type","string"))).put("required",new JSONArray().put("path"))));result=new JSONObject().put("tools",tools);break;}
   case "tools/call":{JSONObject p=q.getJSONObject("params"),args=p.optJSONObject("arguments");String rel=args==null?"":args.optString("path");File f=rel.isEmpty()?root:FileOps.contained(root,rel);String text;if(p.getString("name").equals("list_files")){File[]fs=f.listFiles();if(fs==null)throw new IOException("Folder unavailable");JSONArray list=new JSONArray();for(File c:fs)list.put(new JSONObject().put("name",c.getName()).put("directory",c.isDirectory()).put("size",c.length()));text=list.toString();}else if(p.getString("name").equals("read_text"))text=new String(FileOps.read(f,1048576),StandardCharsets.UTF_8);else throw new IOException("Unknown tool");result=new JSONObject().put("content",new JSONArray().put(new JSONObject().put("type","text").put("text",text)));break;}
   default:throw new IOException("Method not found");}
   response.put("result",result);
  }catch(Exception e){response.put("error",new JSONObject().put("code",-32602).put("message",e.getMessage()));}return response;}
 }
 static class FilesSupport{static boolean symlink(File f){return java.nio.file.Files.isSymbolicLink(f.toPath());}}
 static Map<String,String>query(String q)throws Exception{Map<String,String>m=new HashMap<>();if(q!=null)for(String part:q.split("&")){String[]p=part.split("=",2);m.put(URLDecoder.decode(p[0],"UTF-8"),p.length>1?URLDecoder.decode(p[1],"UTF-8"):"");}return m;}
 static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace("\"","&quot;").replace("'","&#39;");}
 static void reply(Socket c,int status,String type,byte[]data)throws IOException{OutputStream out=c.getOutputStream();out.write(("HTTP/1.1 "+status+" Response\r\nContent-Type: "+type+"\r\nContent-Length: "+data.length+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(data);out.flush();}
}
